import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative tanh of (load + job) in units of the largest job seen so far (incl. current)."""
    past_max = float(past_jobs.max()) if past_jobs.size else float(job)
    s = max(past_max, float(job), 1e-9)
    return -np.tanh((loads + job) / s)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative clipped ratio of post-placement load to current load, with the clip applied to the load term only: -min((loads+job)/(loads+1e-9), 10)."""
    post = loads + job
    ratio = post / (loads + 1e-9)
    return -np.minimum(ratio, 10.0)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative smallness of the job times an indicator that the machine is among the k emptiest, where k estimates the expected number of remaining giants."""
    m = loads.shape[0]
    if past_jobs.shape[0] == 0:
        med = job
    else:
        med = float(np.median(past_jobs))
    if med <= 0:
        rate = 0.0
    else:
        rate = float(np.mean(past_jobs > 4.0 * med)) if past_jobs.shape[0] > 0 else 0.0
    k = int(round(rate * jobs_left))
    k = max(0, min(k, m - 1))
    if k == 0:
        return np.zeros(m)
    thresh = np.sort(loads)[k - 1]
    in_reserve = (loads <= thresh + 1e-12).astype(float)
    smallness = med / (med + job) if (med + job) > 0 else 0.0
    return -smallness * in_reserve

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Gated negative relative resulting-makespan max(post[c], max other load), active only in the final ~10% of jobs."""
    m = len(loads)
    post = loads + job
    horizon = past_jobs.size + jobs_left
    if horizon <= 0:
        return np.zeros(m)
    gate = min(max(1.0 - jobs_left / (0.1 * horizon), 0.0), 1.0)
    if gate == 0.0:
        return np.zeros(m)
    mx = np.max(loads)
    arg = np.argmax(loads)
    srt = np.sort(loads)
    second = srt[-2] if m > 1 else -np.inf
    other = np.where(np.arange(m) == arg, second, mx)
    M = np.maximum(post, other)
    mean_post = np.mean(post)
    return np.clip(-gate * (M - mean_post) / (mean_post + 1e-9), -1.0, 1.0)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative reservation on the k emptiest post-placement machines, k sized by the near-term giant rate."""
    m = loads.shape[0]
    if past_jobs.size < 5:
        return np.zeros(m)
    med = np.median(past_jobs)
    if med <= 0:
        return np.zeros(m)
    if job > 4.0 * med:
        return np.zeros(m)
    giant_frac = np.mean(past_jobs > 4.0 * med)
    if giant_frac == 0:
        return np.zeros(m)
    k = int(np.ceil(giant_frac * min(jobs_left + 1, m)))
    k = int(np.clip(k, 1, m - 1))
    post = loads + job
    # rank: position in ascending order, ties broken by index (stable sort)
    order = np.argsort(post, kind="stable")
    rank = np.empty(m, dtype=float)
    rank[order] = np.arange(m, dtype=float)
    return -np.maximum(0.0, 1.0 - rank / k)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative graded reservation: penalise machines whose post-placement load is below the 90th-percentile past job size, scaled by that threshold."""
    m = loads.shape[0]
    if past_jobs.size < 5:
        return np.zeros(m)
    theta = float(np.quantile(past_jobs, 0.9))
    if theta <= 0.0:
        return np.zeros(m)
    post = loads + job
    gap = theta - post
    gap = np.clip(gap, 0.0, theta) / theta
    return -gap

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Post-load of machines that stay at or below the current makespan bar (scaled), else negative post-load."""
    bar = np.max(loads)
    post = loads + job
    scale = max(bar, job, 1e-9)
    fits = post <= bar
    if np.any(fits):
        return np.where(fits, post / scale, -post / scale - 1.0)
    else:
        return -post / scale
